&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de r&#244;deur&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_r&#244;deur_0&quot; href=&quot;#Les_arch&#233;types_de_r&#244;deur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-R&#244;deur-(R&#244;deur).html&quot; title=&quot;Archer r&#244;deur&quot;&gt;Archer r&#244;deur&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-Des-Profondeurs-(R&#244;deur).html&quot; title=&quot;Arpenteur des profondeurs&quot;&gt;Arpenteur des profondeurs&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Briseur-De-Guildes-(R&#244;deur).html&quot; title=&quot;Briseur de guildes&quot;&gt;Briseur de guildes&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Rebelle-(R&#244;deur).html&quot; title=&quot;Champion rebelle&quot;&gt;Champion rebelle&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changeforme-(R&#244;deur).html&quot; title=&quot;Changeforme&quot;&gt;Changeforme&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Troph&#233;es-(R&#244;deur).html&quot; title=&quot;Chasseur de troph&#233;es&quot;&gt;Chasseur de troph&#233;es&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Sauvage-(R&#244;deur).html&quot; title=&quot;Chasseur sauvage&quot;&gt;Chasseur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dandy-(R&#244;deur).html&quot; title=&quot;Dandy&quot;&gt;Dandy&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;claireur-De-Larm&#233;e-(R&#244;deur).html&quot; title=&quot;&#201;claireur de l&amp;#39;arm&#233;e&quot;&gt;&#201;claireur de l&#39;arm&#233;e&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fauconnier-(R&#244;deur).html&quot; title=&quot;Fauconnier&quot;&gt;Fauconnier&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flibustier-(R&#244;deur).html&quot; title=&quot;Flibustier&quot;&gt;Flibustier&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-(R&#244;deur).html&quot; title=&quot;Gardien&quot;&gt;Gardien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Des-Vagues-(R&#244;deur).html&quot; title=&quot;Gardien des vagues&quot;&gt;Gardien des vagues&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Poisson-(Race).html&quot; title=&quot;Les hommes-poissons&quot;&gt;Homme-poisson&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-(R&#244;deur).html&quot; title=&quot;Guide&quot;&gt;Guide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-B&#234;tes-(R&#244;deur).html&quot; title=&quot;Ma&#238;tre des b&#234;tes&quot;&gt;Ma&#238;tre des b&#234;tes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Messager-Secret-(R&#244;deur).html&quot; title=&quot;Messager secret&quot;&gt;Messager secret&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ombre-Sauvage-(R&#244;deur).html&quot; title=&quot;Ombre sauvage&quot;&gt;Ombre sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pisteur-Divin-(R&#244;deur).html&quot; title=&quot;Pisteur divin&quot;&gt;Pisteur divin&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Infiltr&#233;-(R&#244;deur).html&quot; title=&quot;R&#244;deur infiltr&#233;&quot;&gt;R&#244;deur infiltr&#233;&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Libre-Du-Nirmathas-(R&#244;deur).html&quot; title=&quot;R&#244;deur libre des for&#234;ts&quot;&gt;R&#244;deur libre des for&#234;ts&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Spirituel-(R&#244;deur).html&quot; title=&quot;R&#244;deur spirituel&quot;&gt;R&#244;deur spirituel&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Urbain-(R&#244;deur).html&quot; title=&quot;R&#244;deur urbain&quot;&gt;R&#244;deur urbain&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-Des-Chevaux-(R&#244;deur).html&quot; title=&quot;Seigneur des chevaux&quot;&gt;Seigneur des chevaux&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sentinelle-(R&#244;deur).html&quot; title=&quot;Sentinelle&quot;&gt;Sentinelle&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tirailleur-(R&#244;deur).html&quot; title=&quot;Tirailleur&quot;&gt;Tirailleur&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transporteur-(R&#244;deur).html&quot; title=&quot;Transporteur&quot;&gt;Transporteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-(R&#244;deur).html&quot; title=&quot;Trappeur&quot;&gt;Trappeur&lt;/a&gt; (UM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Du-Cr&#233;puscule-(R&#244;deur).html&quot; title=&quot;Traqueur du cr&#233;puscule&quot;&gt;Traqueur du cr&#233;puscule&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Fetchelin-(Race).html&quot; title=&quot;Les fetchelins&quot;&gt;Fetchelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Sauvage-(R&#244;deur).html&quot; title=&quot;Traqueur sauvage&quot;&gt;Traqueur sauvage&lt;/a&gt; (UC)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Demi-elfe.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Demi-elfe.ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Demi-elfe.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;demi-elfes&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Certains demi-elfes se sentent tellement isol&#233;s qu’ils partent mener une vie solitaire dans les &#233;tendues sauvages. Ces r&#244;deurs se d&#233;placent dans la nature comme des ombres et tissent des liens &#233;troits avec leur environnement plut&#244;t que de chercher le r&#233;confort et l’aide de compagnons. Ils sont mal &#224; l’aise dans les villes et les zones urbanis&#233;es, mais ils sont tr&#232;s dou&#233;s pour utiliser leur environnement &#224; leur avantage. Ils filent &#224; travers les buissons et sur les terrains accident&#233;s avec une gr&#226;ce surnaturelle et se servent de la terre elle-m&#234;me pour immobiliser leurs ennemis.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Cœur sauvage (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Cœur_sauvage_Ext_0&quot; href=&quot;#Cœur_sauvage_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, l’ombre sauvage ajoute seulement 1/2 niveau de classe &#224; ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#EMPATHIESAUVAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;empathie sauvage&lt;/a&gt; en zone urbaine et 1/4 de son niveau de classe &#224; ses tests pour suivre une &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PISTAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;piste&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;identifier des traces&lt;/a&gt; en zone urbaine. Dans les autres environnements, on consid&#232;re qu’elle a deux niveaux de plus qu’en r&#233;alit&#233; quand elle d&#233;termine les bonus de ces tests. Ce pouvoir modifie les pouvoirs &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PISTAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;pistage&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#EMPATHIESAUVAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;empathie sauvage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Environnement de pr&#233;dilection (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Environnement_de_pr&#233;dilection_Ext_1&quot; href=&quot;#Environnement_de_pr&#233;dilection_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, quand l’ombre sauvage choisit un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur#Environnementdepredilection.html&quot; title=&quot;environnement de pr&#233;dilection&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt;, elle ne peut pas choisir environnement urbain. Elle n’y a pas davantage droit par la suite, quand elle choisit un nouvel environnement au niveau 8 puis tous les cinq niveaux. Ce pouvoir modifie celui d’&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur#Environnementdepredilection.html&quot; title=&quot;environnement de pr&#233;dilection&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;placement facilit&#233; (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;placement_facilit&#233;_Ext_2&quot; href=&quot;#D&#233;placement_facilit&#233;_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ce pouvoir fonctionne comme le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#DEPLACEMENTFACILITE&quot; title=&quot;Le r&#244;deur&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt; de r&#244;deur de niveau 7, mais l’ombre sauvage l’obtient au niveau 4. Il remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PACTEDUCHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;pacte du chasseur&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;placement sans entrave (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;placement_sans_entrave_Ext_3&quot; href=&quot;#D&#233;placement_sans_entrave_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 7, tant que l’ombre sauvage se trouve dans un environnement de pr&#233;dilection, son &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#DEPLACEMENTFACILITE&quot; title=&quot;Le r&#244;deur&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt; fonctionne dans tous les &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position#Terraindifficile.html&quot; title=&quot;terrain difficile&quot;&gt;terrains difficiles&lt;/a&gt;, m&#234;me dans les zones modifi&#233;es par magie ou enchant&#233;es pour g&#234;ner le mouvement. Ce pouvoir remplace le &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#DEPLACEMENTFACILITE&quot; title=&quot;Le r&#244;deur&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt; du r&#244;deur de niveau 7.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Harc&#232;lement (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Harc&#232;lement_Ext_4&quot; href=&quot;#Harc&#232;lement_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, l’ombre utilise sa connaissance du terrain pour lancer des attaques vicieuses. Ces attaques font tr&#233;bucher ses adversaires ou tirent parti de l’environnement de pr&#233;dilection de l’ombre sauvage pour les enchev&#234;trer. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, l’ombre choisit une cible en ligne de mire, pr&#233;sente dans un de ses environnements de pr&#233;dilection, et d&#233;cide d’en faire une proie &#224; harceler. Une fois qu’elle a d&#233;sign&#233; une proie, &#224; chaque fois qu’elle la touche avec une arme de corps &#224; corps ou &#224; distance (manufactur&#233;e ou naturelle), elle l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Enchev&#234;tr&#233;.html&quot; title=&quot;Enchev&#234;tr&#233;&quot;&gt;enchev&#234;tre&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. L’ombre sauvage ne peut choisir qu’une proie &#224; harceler &#224; la fois et il s’agit obligatoirement d’un de ses &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur#Ennemijure.html&quot; title=&quot;ennemi jur&#233;&quot;&gt;ennemis jur&#233;s&lt;/a&gt;. Elle peut dissiper l’effet quand elle le d&#233;sire, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;, mais doit attendre 24 heures avant de choisir une nouvelle proie &#224; harceler. Si l’ombre a la preuve que sa proie est morte, elle peut choisir d’en harceler une nouvelle une heure plus tard. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PROIEDUCHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;proie du chasseur&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Traqueur sauvage (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Traqueur_sauvage_Ext_5&quot; href=&quot;#Traqueur_sauvage_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 14, l’ombre sauvage apprend &#224; utiliser au mieux son environnement naturel pour dissimuler sa position lors d’un combat. Quand l’ombre sauvage se trouve dans un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur#Environnementdepredilection.html&quot; title=&quot;environnement de pr&#233;dilection&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt; et qu’un &#233;l&#233;ment du terrain lui donne un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Abri.html&quot; title=&quot;abri&quot;&gt;abri&lt;/a&gt;, les bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; de cet abri augmentent de 1. De plus, tant qu’elle se trouve dans un environnement de pr&#233;dilection, si elle gagne un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Camouflage.html&quot; title=&quot;camouflage&quot;&gt;camouflage&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Camouflagetotal.html&quot; title=&quot;camouflage total&quot;&gt;camouflage total&lt;/a&gt;, les chances de la rater augmentent de 10 %. Le bonus de l’abri augmente encore de 1 et les chances de rater de 10 % de plus aux niveaux 16 et 19 (pour un maximum respectif de +3 et +30 % au niveau 20). Ce pouvoir remplace celui de &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CAMOUFLAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;camouflage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre du terrain (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_du_terrain_Ext_6&quot; href=&quot;#Ma&#238;tre_du_terrain_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 19, l’ombre sauvage peut utiliser sa capacit&#233; de harc&#232;lement contre des cr&#233;atures autres que ses ennemis jur&#233;s ou d&#233;penser une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour d&#233;signer deux ennemis jur&#233;s comme cibles de son harc&#232;lement. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PROIEDUMAITRECHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;proie du ma&#238;tre chasseur&lt;/a&gt;.
